param([Parameter(Mandatory=$true)][int]$MochaPid,[Parameter(Mandatory=$true)][string]$ResultPath)
$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
function Find-Id($root,[string]$id){$c=New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::AutomationIdProperty,$id);$a=$root.FindAll([System.Windows.Automation.TreeScope]::Subtree,$c);if($a.Count -ne 1){throw "Expected one UIA automation id $id; found $($a.Count)."};$a.Item(0)}
function Read-Frame($slider){$p=$null;if(-not $slider.TryGetCurrentPattern([System.Windows.Automation.RangeValuePattern]::Pattern,[ref]$p)){throw 'Frame slider lacks RangeValuePattern.'};[int][Math]::Round(([System.Windows.Automation.RangeValuePattern]$p).Current.Value)}
function Invoke-Exact($e,[string]$label){$p=$null;if(-not $e.TryGetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern,[ref]$p)){throw "$label lacks InvokePattern."};([System.Windows.Automation.InvokePattern]$p).Invoke()}
$p=Get-Process -Id $MochaPid -ErrorAction Stop;if(-not $p.Responding -or $p.MainWindowHandle -eq 0 -or $p.MainWindowTitle -notlike 'Mocha AE*'){throw 'Responsive proof-owned Mocha main window required.'}
$root=[System.Windows.Automation.AutomationElement]::FromHandle($p.MainWindowHandle);$slider=Find-Id $root 'frmMain.centralArea.sldrFrameNumber';$next=Find-Id $root 'frmMain.centralArea.timelineControlsW.transportControlsW.btnNextFrame';$before=Read-Frame $slider;if($before -ne 0){throw "Seek proof must start at frame 0; got $before."};$sw=[Diagnostics.Stopwatch]::StartNew();Invoke-Exact $next 'Next Frame';$d=(Get-Date).AddSeconds(3);do{Start-Sleep -Milliseconds 25;$after=Read-Frame $slider;if($after -eq 1){break}}while((Get-Date)-lt$d);$sw.Stop();if($after -ne 1){throw "Next Frame did not reach frame 1; got $after."};$o=[ordered]@{ok=$true;beforeFrame=$before;afterFrame=$after;transportActionMs=[Math]::Round($sw.Elapsed.TotalMilliseconds,3);automationId=[string]$next.Current.AutomationId};$dir=Split-Path -Parent $ResultPath;if($dir){New-Item -ItemType Directory -Force -Path $dir|Out-Null};[IO.File]::WriteAllText($ResultPath,(($o|ConvertTo-Json -Depth 6)+[Environment]::NewLine),(New-Object Text.UTF8Encoding($false)));$o|ConvertTo-Json -Depth 6